        img.onerror = () => mark("t-inline", "inlineDataImage", false, "error event");
        img.src = dataUri;
      })();

      // B. external image from a declared-by-permissive origin
      (function probeCdnImage() {
        const url = "https://cdn.jsdelivr.net/npm/simple-icons@13.0.0/icons/nodedotjs.svg";
        const img = new Image();
        img.onload = () => mark("t-cdn", "externalImageDeclared", true, url);
        img.onerror = () => mark("t-cdn", "externalImageDeclared", false, url);
        img.src = url;
        setTimeout(() => {
          if (!report.probes.externalImageDeclared) {
            mark("t-cdn", "externalImageDeclared", false, "timeout (no load/error within 6s)");
          }
        }, 6000);
      })();

      // C. external stylesheet, declared by neither resource
      (function probeFont() {
        const link = document.getElementById("probe-font");
        const settle = () => {
          // A blocked stylesheet has no cssRules and sheet is null.
          const loaded = !!link.sheet;
          mark(
            "t-font",
            "externalStylesheetUndeclared",
            loaded,
            loaded ? "sheet object present" : "link.sheet is null",
          );
        };
        if (document.readyState === "complete") setTimeout(settle, 500);
        else window.addEventListener("load", () => setTimeout(settle, 500));
      })();

      // D. fetch to a declared-by-permissive origin
      (function probeFetchDeclared() {
        const url = "https://api.github.com/zen";
        const ctl = new AbortController();
        const timer = setTimeout(() => ctl.abort(), 6000);
        fetch(url, { signal: ctl.signal })
          .then((r) => r.text())
          .then((t) =>
            mark("t-fetch-declared", "fetchDeclared", true, "HTTP ok, body: " + t.slice(0, 40)),
          )
          .catch((e) => mark("t-fetch-declared", "fetchDeclared", false, e.name + ": " + e.message))
          .finally(() => clearTimeout(timer));
      })();

      // E. fetch to an origin declared by neither resource
      (function probeFetchUndeclared() {
        const url = "https://example.com/";
        const ctl = new AbortController();
        const timer = setTimeout(() => ctl.abort(), 6000);
        fetch(url, { mode: "no-cors", signal: ctl.signal })
          .then(() => mark("t-fetch-undeclared", "fetchUndeclared", true, "request left the frame"))
          .catch((e) =>
            mark("t-fetch-undeclared", "fetchUndeclared", false, e.name + ": " + e.message),
          )
          .finally(() => clearTimeout(timer));
      })();

      // F. nested iframe
      (function probeNestedFrame() {
        const f = document.createElement("iframe");
        f.style.display = "none";
        f.src = "https://example.com/";
        f.onload = () => mark("t-frame", "nestedIframe", true, "load event fired");
        f.onerror = () => mark("t-frame", "nestedIframe", false, "error event");
        document.body.appendChild(f);
        setTimeout(() => {
          if (!report.probes.nestedIframe) {
            mark("t-frame", "nestedIframe", false, "no load event within 6s");
          }
        }, 6000);
      })();

      // ----------------------------------------------------------------- //
      // MCP Apps lifecycle over postMessage (SEP-1865 §Transport Layer).
      // Written without the SDK on purpose: the spec documents this raw shape,
      // and doing it by hand means the experiment tests the protocol rather
      // than a client library's convenience wrapper.
      // ----------------------------------------------------------------- //
      let nextId = 1;
      const pending = new Map();

      function sendRequest(method, params) {
        const id = nextId++;
        report.lifecycle.push({ dir: "view->host", kind: "request", method, id });
        emit();
        window.parent.postMessage({ jsonrpc: "2.0", id, method, params }, "*");
        return new Promise((resolve, reject) => {
          pending.set(id, { resolve, reject });
          setTimeout(() => {
            if (pending.has(id)) {
              pending.delete(id);
              reject(new Error("timeout waiting for response to " + method));
            }
          }, 5000);
        });
      }

      function sendNotification(method, params) {
        report.lifecycle.push({ dir: "view->host", kind: "notification", method });
        emit();
        window.parent.postMessage({ jsonrpc: "2.0", method, params }, "*");
      }

      window.addEventListener("message", (event) => {
        const msg = event.data;
        if (!msg || msg.jsonrpc !== "2.0") return;

        if (msg.id !== undefined && pending.has(msg.id)) {
          const { resolve, reject } = pending.get(msg.id);
          pending.delete(msg.id);
          report.lifecycle.push({ dir: "host->view", kind: "response", id: msg.id });
          if (msg.error) reject(new Error(JSON.stringify(msg.error)));
          else resolve(msg.result);
          emit();
          return;
        }

        if (msg.method) {
          report.lifecycle.push({ dir: "host->view", kind: "notification", method: msg.method });
          if (msg.method === "ui/notifications/tool-result") {
            report.toolResult = msg.params;
            renderData(msg.params);
          }
          if (msg.method === "ui/notifications/tool-input") {
            report.toolInput = msg.params;
          }
          emit();
        }
      });

      function renderData(params) {
        const sc = params && params.structuredContent;
        const title = document.getElementById("title");
        const host = document.getElementById("data");
        if (!sc || !Array.isArray(sc.unicorns)) {
          host.innerHTML =
            '<p class="fail">tool-result arrived but structuredContent.unicorns was missing.</p>';
          return;
        }
        title.textContent = "Fleet card — " + sc.unicorns.length + " unicorn(s)";
        const rows = sc.unicorns
          .map(
            (u) =>
              "<tr><td>" +
              u.name +
              "</td><td><code>" +
              u.id +
              "</code></td><td>" +
              u.size +
              "</td><td>$" +
              u.hourlyRate +
              "/h</td><td>" +
              (u.available ? "available" : "booked") +
              "</td></tr>",
          )
          .join("");
        host.innerHTML =
          '<table><thead><tr><th>Name</th><th>ID</th><th>Size</th><th>Rate</th><th>Status</th></tr></thead><tbody>' +
          rows +
          "</tbody></table><p>generated at <code>" +
          sc.generatedAt +
          "</code></p>";
      }

      // ----------------------------------------------------------------- //
      // Handshake.
      //
      // Done twice on purpose, to document a trap this experiment fe

ll into.
      //
      // SEP-1865's narrative "you don't need an SDK" example sends
      // `clientInfo` — but that example is for the BASE `initialize` method.
      // The normative type for `ui/initialize` (McpUiInitializeRequest) requires
      // `appInfo`, `appCapabilities`, `protocolVersion`. Copying the narrative
      // example into a `ui/initialize` call gets you rejected, and the first
      // call below records exactly that rejection rather than asserting it.
      // ----------------------------------------------------------------- //
      collectEnv();

      // 1. The wrong shape, sent deliberately.
      sendRequest("ui/initialize", {
        capabilities: {},
        clientInfo: { name: "fleet-card-probe", version: "1.0.0" },
        protocolVersion: "2026-01-26",
      })
        .then((result) => {
          report.lifecycle.push({
            kind: "ui/initialize with clientInfo UNEXPECTEDLY ACCEPTED",
            result,
          });
          emit();
        })
        .catch((e) => {
          report.lifecycle.push({
            kind: "ui/initialize with clientInfo REJECTED (expected)",
            error: String(e),
          });
          emit();
        })
        .finally(() => {
          // 2. The shape the normative schema actually specifies.
          sendRequest("ui/initialize", {
            appInfo: { name: "fleet-card-probe", version: "1.0.0" },
            appCapabilities: { availableDisplayModes: ["inline"] },
            protocolVersion: "2026-01-26",
          })
            .then((result) => {
              report.lifecycle.push({ kind: "ui/initialize with appInfo ACCEPTED", result });
              sendNotification("ui/notifications/initialized", {});
              emit();
            })
            .catch((e) => {
              report.lifecycle.push({ kind: "ui/initialize with appInfo FAILED", error: String(e) });
              sendNotification("ui/notifications/initialized", {});
              emit();
            });
        });

      setTimeout(emit, 8000);
    </script>
  </body>
</html>
